using System;

class Solution
{
    public static int AbsDiff(int a, int b) => Math.Abs(a - b);

    public static int BoxCount(int items, int perBox) => (int)Math.Ceiling(items / (double)perBox);

    public static int Clamp(int value, int low, int high) => Math.Max(low, Math.Min(value, high));
}

