class Solution
{
    public static bool HasBit(int flags, int bit) => (flags & (1 << bit)) != 0;

    public static int SetBit(int flags, int bit) => flags | (1 << bit);

    public static int ClearBit(int flags, int bit) => flags & ~(1 << bit);
}

