    public static string Kind(char c)
    {
        if (char.IsDigit(c))
        {
            return "数字";
        }
        if (char.IsWhiteSpace(c))
        {
            return "空白";
        }
        if (char.IsUpper(c))
        {
            return "大文字";
        }
        if (char.IsLetter(c))
        {
            return "文字";
        }
        return "その他";
    }

    public static int CountDigits(string text)
    {
        int count = 0;
        foreach (char c in text)
        {
            if (char.IsDigit(c))
            {
                count++;
            }
        }
        return count;
    }
}

