using System;

class Solution
{
    public static int CountDigits(int n)
    {
        if (n == 0) return 1;

        long value = n;
        if (value < 0) value = -value;

        int count = 0;
        while (value > 0)
        {
            value /= 10;
            count++;
        }
        return count;
    }
}

