using System;
using System.Text;

class Solution
{
    public static string RepeatAtLeastOnce(string text, int times)
    {
        var builder = new StringBuilder();
        int done = 0;
        do
        {
            builder.Append(text);
            done++;
        } while (done < times);

        return builder.ToString();
    }
}

