using System;

class Solution
{
    public static int SumEvens(int[] numbers)
    {
        int total = 0;
        foreach (int n in numbers)
        {
            if (n < 0) break;         // ここでループそのものを終える
            if (n % 2 != 0) continue; // この 1 周だけ飛ばす
            total += n;
        }
        return total;
    }
}

