answer_code:
using System;

class Solution
{
    public static int[] RowSums(int[,] grid)
    {
        int rows = grid.GetLength(0);
        int cols = grid.GetLength(1);

        int[] sums = new int[rows];
        for (int r = 0; r < rows; r++)
        {
            int total = 0;
            for (int c = 0; c < cols; c++)
            {
                total += grid[r, c];
            }
            sums[r] = total;
        }
        return sums;
    }
}

