using System;

class Solution
{
    public static int TotalSum(int[][] rows)
    {
        int total = 0;
        foreach (int[] row in rows)
        {
            foreach (int value in row)
            {
                total += value;
            }
        }
        return total;
    }

    public static int LongestRowLength(int[][] rows)
    {
        int longest = 0;
        foreach (int[] row in rows)
        {
            if (row.Length > longest)
            {
                longest = row.Length;
            }
        }
        return longest;
    }
}

