using System;
using System.Collections.Generic;

class Solution
{
    public static List<string> SortByLength(List<string> words)
    {
        words.Sort((a, b) =>
        {
            if (a.Length != b.Length)
            {
                return a.Length.CompareTo(b.Length);
            }
            return string.CompareOrdinal(a, b);
        });
        return words;
    }
}

