using System.Collections.Generic;

class Solution
{
    public static int SumByPrefix(Dictionary<string, int> sales, string prefix)
    {
        int total = 0;
        foreach (KeyValuePair<string, int> pair in sales)
        {
            if (pair.Key.StartsWith(prefix))
            {
                total += pair.Value;
            }
        }
        return total;
    }

    public static int LargestValue(Dictionary<string, int> sales)
    {
        int largest = 0;
        foreach (int value in sales.Values)
        {
            if (value > largest)
            {
                largest = value;
            }
        }
        return largest;
    }
}

