using System.Collections.Generic;

class Solution
{
    public static int CountDuplicates(int[] numbers)
    {
        var seen = new HashSet<int>();
        int duplicates = 0;
        foreach (int n in numbers)
        {
            if (!seen.Add(n))
            {
                duplicates++;
            }
        }
        return duplicates;
    }
}

