class Solution
{
    public static List<int> CommonSorted(int[] a, int[] b)
    {
        var set = new HashSet<int>(a);
        set.IntersectWith(b);
        var result = new List<int>(set);
        result.Sort();
        return result;
    }

    public static List<int> OnlyInFirst(int[] a, int[] b)
    {
        var set = new HashSet<int>(a);
        set.ExceptWith(b);
        var result = new List<int>(set);
        result.Sort();
        return result;
    }
}

