answer_code:
using System.Collections.Generic;

class Solution
{
    public static string NextInLine(string[] names, int served)
    {
        var queue = new Queue<string>();
        foreach (string name in names)
        {
            queue.Enqueue(name);
        }
        for (int i = 0; i < served && queue.Count > 0; i++)
        {
            queue.Dequeue();
        }
        if (queue.Count == 0)
        {
            return "(なし)";
        }
        return queue.Peek();
    }
}

