using System.Collections.Generic;

class Solution
{
    public static bool IsBalanced(string text)
    {
        var stack = new Stack<char>();
        foreach (char c in text)
        {
            if (c == '(' || c == '[')
            {
                stack.Push(c);
            }
            else if (c == ')')
            {
                if (stack.Count == 0 || stack.Pop() != '(') { return false; }
            }
            else if (c == ']')
            {
                if (stack.Count == 0 || stack.Pop() != '[') { return false; }
            }
        }
        return stack.Count == 0;
    }
}

