using System;

class Solution
{
    public static long FactorialSum(int n)
    {
        long Factorial(int k)
        {
            long acc = 1;
            for (var i = 2; i <= k; i++) acc *= i;
            return acc;
        }

        long total = 0;
        for (var i = 1; i <= n; i++) total += Factorial(i);
        return total;
    }
}

